function ranked(){return state.plans.map(p=>({...p,votes:state.preferences.filter(x=>x.preference===p.tag).length,fit:p.cost<=state.budget})).sort((a,b)=>Number(b.fit)-Number(a.fit)||b.votes-a.votes||a.cost-b.cost)}
function render(){$('#app').innerHTML=`<div class="grid"><div>${panel('每个人都能说出喜欢',`<form id="preference" class="stack"><div class="fields">${field('家庭成员代号','member','text','','required maxlength="20"')}${select('最想体验','preference',['自然','文化','玩乐'])}</div><button class="primary">加入 / 更新偏好</button></form>${state.preferences.map(x=>`<div class="item"><span>${esc(x.member)} · ${x.preference}</span><button class="small" data-action="${esc(x.member)}">移除</button></div>`).join('')}`)}${panel('候选方案对比',ranked().map(p=>`<div class="item"><div><span class="tag">${p.tag}</span><h3 style="margin:9px 0">${esc(p.name)}</h3><p>${p.route.map(esc).join(' → ')}</p><p>${p.votes} 人偏好匹配 · ${p.fit?'预算内':'超预算'}</p></div><div><b>¥${p.cost}</b><p><button data-plan="${p.id}" class="small ${state.selected===p.id?'selected':''}" ${p.fit?'':'disabled'}>${state.selected===p.id?'已选择':'选这条'}</button></p></div></div>`).join(''))}</div><div>${panel('给旅行画个边界',`<label>家庭总预算：<strong id="budget-number">${state.budget} 元</strong><input id="budget" type="range" min="100" max="1500" step="50" value="${state.budget}"></label><p class="notice">排序规则：优先预算内，再按匹配人数，最后按费用。费用和路线都是课堂虚构数据，不是实时报价。</p>`,'tint')}${panel('家庭出游决定',state.selected?(()=>{const p=state.plans.find(x=>x.id===state.selected);return `<h2>${esc(p.name)}</h2><p>${p.route.map(esc).join(' → ')}</p><p>示例费用 ${p.cost} 元；剩余预算 ${state.budget-p.cost} 元。</p>`})():empty('听完家人的偏好，再选一条路线。'))}</div></div>`;
form('preference',v=>{state.preferences=state.preferences.filter(x=>x.member!==v.member.trim());state.preferences.push({...v,member:v.member.trim()});commit()});actions('[data-action]',id=>{state.preferences=state.preferences.filter(x=>x.member!==id);commit()});$('#budget').oninput=e=>$('#budget-number').textContent=e.target.value+' 元';$('#budget').onchange=e=>{state.budget=+e.target.value;if(state.selected&&state.plans.find(x=>x.id===state.selected).cost>state.budget)state.selected=null;commit()};$$('[data-plan]').forEach(b=>b.onclick=()=>{state.selected=b.dataset.plan;commit()})}render();
